const S = {interests:[],w:{},bubble:0,shown:[],likes:0,skips:0,maxShown:false};
const clamp = (v,a=0,b=100) => Math.max(a,Math.min(b,v));
const score = g => g.tags.reduce((s,t) => s+(S.w[t]||0),0)/g.tags.length;

function bubble(d) {
  S.bubble = clamp(S.bubble+d);
  const p = S.bubble;
  document.getElementById('bubbleBar').style.width = p+'%';
  document.getElementById('bubbleBarGlow').style.width = p+'%';
  document.getElementById('bubbleValue').textContent = p+'%';
  document.body.classList.toggle('bubble-mid',p>=35);
  document.body.classList.toggle('bubble-high',p>=60);
  document.body.classList.toggle('bubble-extreme',p>=85);
  if (p>=60) glitch();
  if (p>=100 && !S.maxShown) { S.maxShown=true; setTimeout(showMax,700); }
  updateStats();
}

function glitch() {
  const el = document.getElementById('glitchOverlay');
  el.classList.remove('active');
  void el.offsetWidth;
  el.classList.add('active');
}

function initSakura() {
  const bg = document.getElementById('sakuraBg');
  for (let i=0;i<18;i++) {
    const p = document.createElement('div');
    p.className = 'petal';
    p.style.cssText = `left:${Math.random()*100}%;animation-delay:${Math.random()*8}s;animation-duration:${6+Math.random()*6}s;opacity:${0.3+Math.random()*0.5};font-size:${12+Math.random()*10}px;`;
    p.textContent = ['*','o','+','x'][Math.floor(Math.random()*4)];
    bg.appendChild(p);
  }
}

function initGrid() {
  const skip = new Set(['детское','милое','ретро','махо-сёдзё','спорт']);
  const tags = [...new Set(ANIME.flatMap(g=>g.tags).filter(t=>!skip.has(t)))];
  const labels = {'сёнэн':'Сёнэн','сейнэн':'Сэйнэн','исэкай':'Исэкай','романтика':'Романтика','тёмное фэнтези':'Тёмное фэнтези','психология':'Психология','боевые искусства':'Боевые искусства','трагедия':'Трагедия','комедия':'Комедия','дружба':'Дружба','предательство':'Предательство','стать сильнейшим':'Стать лучшим','любовная линия':'Романтика++','петля времени':'Петля времени','власть':'Власть','хоррор':'Хоррор','приключения':'Приключения','музыка':'Музыка','школа':'Школа','стратегия':'Стратегия','взросление':'Взросление','смысл жизни':'Философия','семья':'Семья','слезы':'Драма','социальная критика':'Социальное','тёмный герой':'Тёмный герой','детектив':'Детектив','культовое':'Культовое','меха':'Меха','трансформация':'Трансформация','фэнтези':'Фэнтези','сверхъестественное':'Сверхъестественное','наука':'Науч. фантастика','гениальный герой':'Гений','словесные игры':'Интеллектуальное','история':'Историческое','политика':'Политика','насилие':'Взрослый контент','свобода':'Свобода','детское — но нет':'Обманчивая завязка','криминал':'Криминал','война':'Война','магия':'Магия','природа':'Природа','медитативное':'Медитативное','мистика':'Мистика','технологии':'Технологии','шпионаж':'Шпионаж','пародия':'Пародия','супергерои':'Супергерои'};
  const grid = document.getElementById('genreGrid');
  [...new Set(tags)].forEach(tag => {
    const el = document.createElement('div');
    el.className = 'genre-tag';
    el.textContent = labels[tag]||tag;
    el.onclick = () => {
      const i = S.interests.indexOf(tag);
      if (i===-1) { S.interests.push(tag); el.classList.add('selected'); }
      else { S.interests.splice(i,1); el.classList.remove('selected'); }
      document.getElementById('btnStart').disabled = !S.interests.length;
    };
    grid.appendChild(el);
  });
}

document.getElementById('btnStart').addEventListener('click',() => {
  S.interests.forEach(t => S.w[t]=1);
  ANIME.forEach(g => g.tags.forEach(t => { if(!(t in S.w)) S.w[t]=0.05; }));
  document.getElementById('screen-intro').classList.remove('active');
  document.getElementById('screen-feed').classList.add('active');
  updateSidebar();
  loadCards();
});

function loadCards(burst=false) {
  const box = document.getElementById('feedCards');
  const pool = burst
    ? [...BURST,...ANIME.filter(g=>!S.shown.includes(g.title)).sort((a,b)=>score(a)-score(b)).slice(0,2)]
    : ANIME.filter(g=>!S.shown.includes(g.title)).map(g=>({g,s:score(g)+Math.random()*0.12})).sort((a,b)=>b.s-a.s).slice(0,5).map(x=>x.g);
  pool.forEach(g => { S.shown.push(g.title); box.appendChild(makeCard(g)); });
  updateTopTags();
}

function makeCard(g) {
  const radical = (S.bubble>=55&&g.r>=2)||(S.bubble>=78&&g.r>=1);
  const matchTags = (g.tags||[]).filter(t=>(S.w[t]||0)>0.5);
  const rel = Math.round(Math.min(100,score(g)*100+Math.random()*8));
  const div = document.createElement('div');
  div.className = 'anime-card'+(radical?' radical':'')+(g.burst?' burst-card':'');
  if (g.burst) {
    div.innerHTML = `<div class="burst-inner"><div class="burst-title">${g.title}</div><div class="burst-desc">${g.desc}</div><div class="burst-tags">${(g.tags||[]).map(t=>`<span class="burst-tag">#${t}</span>`).join('')}</div></div>`;
    return div;
  }
  const tagLine = (g.tags||[]).map(t=>`<span class="ctag${matchTags.includes(t)?' match':''}">#${t}</span>`).join('');
  div.innerHTML = `
    <div class="card-top">
      <div class="card-meta"><span class="card-year">${g.year}</span><span class="card-studio">${g.studio}</span><span class="card-eps">${g.episodes} эп.</span></div>
      ${radical?`<span class="card-radical-badge">РАДИКАЛЬНАЯ РЕКОМЕНДАЦИЯ</span>`:`<div class="card-rel-bar"><div class="card-rel-fill" style="width:${rel}%"></div><span class="card-rel-val">${rel}%</span></div>`}
    </div>
    <div class="card-title">${g.title}</div>
    <div class="card-desc">${radical&&g.rdesc?g.rdesc:g.desc}</div>
    <div class="card-tags">${tagLine}</div>
    <div class="card-actions">
      <button class="btn-like">В список</button>
      <button class="btn-skip">Не интересует</button>
      <button class="btn-why">Почему это?</button>
    </div>
    <div class="card-why-panel" style="display:none">${g.why}</div>`;
  div.querySelector('.btn-like').onclick = () => {
    S.likes++;
    (g.tags||[]).forEach(t => S.w[t]=clamp((S.w[t]||0)+0.22,0,1));
    Object.keys(S.w).forEach(t => { if(!(g.tags||[]).includes(t)) S.w[t]=Math.max(0,(S.w[t]||0)-0.04); });
    bubble(+7);
    updateSidebar();
    div.style.cssText='transition:opacity .3s,transform .3s;opacity:0;transform:translateX(16px)';
    setTimeout(()=>{ div.remove(); loadCards(); },300);
  };
  div.querySelector('.btn-skip').onclick = () => {
    S.skips++;
    (g.tags||[]).forEach(t => S.w[t]=Math.max(0,(S.w[t]||0)-0.08));
    bubble(+1);
    updateSidebar();
    div.style.cssText='transition:opacity .3s;opacity:0';
    setTimeout(()=>div.remove(),300);
  };
  div.querySelector('.btn-why').onclick = () => {
    const panel = div.querySelector('.card-why-panel');
    panel.style.display = panel.style.display==='none'?'block':'none';
  };
  return div;
}

function updateSidebar() {
  const labels = {'сёнэн':'Сёнэн','сейнэн':'Сэйнэн','исэкай':'Исэкай','романтика':'Романтика'};
  document.getElementById('sidebarTags').innerHTML = S.interests.map(t => {
    const p = Math.round((S.w[t]||0)*100);
    return `<div class="sidebar-tag"><span class="stag-name">${labels[t]||t}</span><span class="stag-val">${p}%</span><div class="stag-bar" style="width:${p}%"></div></div>`;
  }).join('');
  updateTopTags();
  updateStats();
}

function updateTopTags() {
  document.getElementById('topTags').innerHTML = Object.entries(S.w).filter(([,v])=>v>0.35).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([t])=>`<span class="top-tag-chip">#${t}</span>`).join('');
}

function updateStats() {
  document.getElementById('sidebarStats').innerHTML = `<div class="stat-row"><span>Лайков</span><span>${S.likes}</span></div><div class="stat-row"><span>Пропущено</span><span>${S.skips}</span></div><div class="stat-row"><span>Просмотрено</span><span>${S.shown.length}</span></div><div class="stat-row"><span>Пузырь</span><span>${S.bubble}%</span></div>`;
}

document.getElementById('btnMore').onclick = () => { S.shown=[]; loadCards(); };

document.getElementById('btnBurst').onclick = () => {
  Object.keys(S.w).forEach(t=>S.w[t]=0.05);
  S.interests.forEach(t=>S.w[t]=0.3);
  bubble(-S.bubble+3);
  S.shown=[];
  S.maxShown=false;
  document.getElementById('feedCards').innerHTML='';
  loadCards(true);
  glitch();
  updateSidebar();
  document.body.className='';
  const bar=document.getElementById('bubbleBar');
  bar.style.background='linear-gradient(90deg,#7c3aed,#a855f7)';
  setTimeout(()=>bar.style.background='',2500);
};

document.getElementById('btnAlgo').addEventListener('click',() => {
  const top5 = Object.entries(S.w).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const panel = document.getElementById('algoPanel');
  panel.innerHTML = `<div class="algo-inner"><div class="algo-badge">КАК РАБОТАЕТ АЛГОРИТМ</div><div class="algo-desc">Каждый лайк <strong>+22%</strong> к весам тегов карточки.<br>Другие теги снижаются на <strong>-4%</strong> за каждый лайк.<br>При пузыре 55% — более сильный контент выходит вперёд.<br>При пузыре 85% — только крайние позиции в ленте.</div><div class="algo-section-title">ТЕКУЩИЕ ВЕСА ТЕГОВ</div><div class="algo-bars">${top5.map(([t,v])=>`<div class="algo-row"><span class="algo-tag">#${t}</span><div class="algo-track"><div class="algo-fill" style="width:${Math.round(v*100)}%"></div></div><span class="algo-val">${Math.round(v*100)}%</span></div>`).join('')}</div><div class="algo-meta">Лайков: ${S.likes} · Пропущено: ${S.skips} · Пузырь: ${S.bubble}% · Просмотрено: ${S.shown.length}</div><button class="algo-close" id="algoClose">Закрыть</button></div>`;
  panel.style.display='flex';
  document.getElementById('algoClose').onclick = ()=>panel.style.display='none';
});

document.getElementById('btnCompare').addEventListener('click',() => {
  const tagsA = S.interests;
  const all = [...new Set(ANIME.flatMap(g=>g.tags))];
  const tagsB = all.filter(t=>!tagsA.includes(t)).sort(()=>Math.random()-.5).slice(0,3);
  document.getElementById('userALabel').textContent = tagsA.slice(0,3).join(', ');
  document.getElementById('userBLabel').textContent = tagsB.join(', ');
  const topFor = tags => {
    const w = Object.fromEntries(tags.map(t=>[t,1]));
    return ANIME.map(g=>({g,s:g.tags.reduce((a,t)=>a+(w[t]||0),0)/g.tags.length+Math.random()*0.1})).sort((a,b)=>b.s-a.s).slice(0,4).map(x=>x.g);
  };
  ['A','B'].forEach((side,i)=>{
    const el=document.getElementById('compareFeed'+side);
    el.innerHTML='';
    topFor(i===0?tagsA:tagsB).forEach(g=>{
      el.innerHTML+=`<div class="compare-card"><div class="cc-title">${g.title}</div><div class="cc-meta">${g.year} · ${g.studio}</div><div class="cc-desc">${g.desc}</div><div class="cc-tags">${g.tags.map(t=>`<span class="cc-tag">#${t}</span>`).join('')}</div></div>`;
    });
  });
  document.getElementById('comparePanel').style.display='flex';
});

document.getElementById('btnCloseCompare').addEventListener('click',()=>document.getElementById('comparePanel').style.display='none');

function showMax() {
  const best = ANIME.map(g=>({g,s:score(g)+Math.random()*0.06})).sort((a,b)=>b.s-a.s)[0].g;
  const topProf = Object.entries(S.w).filter(([,v])=>v>0.3).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([t])=>t);
  const ov = document.getElementById('maxBubbleOverlay');
  ov.innerHTML = `<div class="max-inner"><div class="max-flicker"></div><div class="max-badge">ПУЗЫРЬ ДОСТИГ 100%</div><div class="max-subtitle">Алгоритм проанализировал ${S.likes} лайков и ${S.skips} пропусков<br>и вычислил идеальное аниме для твоего профиля</div><div class="max-card"><div class="max-card-meta"><span>${best.year}</span><span>${best.studio}</span><span>${best.episodes} эп.</span></div><div class="max-title">${best.title}</div><div class="max-pitch">${best.desc}</div><div class="max-why-box"><div class="max-why-label">ПОЧЕМУ ЭТО ИДЕАЛЬНО ДЛЯ ТЕБЯ</div><div class="max-why">${best.why}</div></div><div class="max-tags">${best.tags.map(t=>`<span class="max-tag">#${t}</span>`).join('')}</div></div><div class="max-profile"><div class="max-profile-label">Профиль интересов</div><div class="max-ptags">${topProf.map(t=>`<span class="max-ptag">#${t}</span>`).join('')}</div></div><div class="max-actions"><button id="maxCont">Продолжить просмотр</button><button id="maxReset" class="max-reset">Сломать пузырь</button></div></div>`;
  ov.style.display='flex';
  requestAnimationFrame(()=>ov.classList.add('active'));
  document.getElementById('maxCont').onclick = ()=>{ ov.classList.remove('active'); setTimeout(()=>{ov.style.display='none';S.maxShown=false;},500); };
  document.getElementById('maxReset').onclick = ()=>{ ov.classList.remove('active'); setTimeout(()=>{ov.style.display='none';document.getElementById('btnBurst').click();},400); };
}

function randomEvent() {
  if (S.bubble<15) return;
  const ev = EVENTS[Math.floor(Math.random()*EVENTS.length)];
  const box = document.createElement('div');
  box.className='event-card';
  box.innerHTML=`<div class="event-txt">${ev.txt}</div>${ev.tag?`<button class="event-boost">Усилить #${ev.tag}</button>`:''}`;
  if (ev.tag) {
    box.querySelector('.event-boost').onclick = ()=>{ S.w[ev.tag]=Math.min(1,(S.w[ev.tag]||0)+0.18); bubble(+4); updateSidebar(); box.remove(); };
  }
  const feed=document.getElementById('feedCards');
  feed.insertBefore(box,feed.firstChild);
  setTimeout(()=>{ if(box.parentNode){box.style.cssText='transition:opacity 1s,transform .5s;opacity:0;transform:translateY(-6px)';setTimeout(()=>box.remove(),1000);} },9000);
}

initSakura();
initGrid();
setInterval(randomEvent,22000);